/**
 * Broadcast when a newly powered mesh node wants to find a node num it can use
 * Sent from the phone over bluetooth to set the user id for the owner of this node.
 * Also sent from nodes to each other when a new node signs on (so all clients can have this info)
 * The algorithm is as follows:
 * when a node starts up, it broadcasts their user and the normal flow is for all
 * other nodes to reply with their User as well (so the new node can build its nodedb)
 * If a node ever receives a User (not just the first broadcast) message where
 * the sender node number equals our node number, that indicates a collision has
 * occurred and the following steps should happen:
 * If the receiving node (that was already in the mesh)'s macaddr is LOWER than the
 * new User who just tried to sign in: it gets to keep its nodenum.
 * We send a broadcast message of OUR User (we use a broadcast so that the other node can
 * receive our message, considering we have the same id - it also serves to let
 * observers correct their nodedb) - this case is rare so it should be okay.
 * If any node receives a User where the macaddr is GTE than their local macaddr,
 * they have been vetoed and should pick a new random nodenum (filtering against
 * whatever it knows about the nodedb) and rebroadcast their User.
 * A few nodenums are reserved and will never be requested:
 * 0xff - broadcast
 * 0 through 3 - for future use
 */
export interface User {
  /**
   * A globally unique ID string for this user.
   * In the case of Signal that would mean +16504442323, for the default macaddr derived id it would be !<8 hexidecimal bytes>.
   * Note: app developers are encouraged to also use the following standard
   * node IDs "^all" (for broadcast), "^local" (for the locally connected node)
   */
  id: string;
  /**
   * A full name for this user, i.e. "Kevin Hester"
   * Limited to 24 bytes of UTF-8: longer names are accepted from senders
   * built against the older 39-byte limit, but devices truncate them before
   * storing or rebroadcasting. Clients should enforce 24 bytes in their UI.
   */
  longName: string;
  /**
   * A VERY short name, ideally two characters.
   * Suitable for a tiny OLED screen
   */
  shortName: string;
  /**
   * Deprecated in Meshtastic 2.1.x
   * This is the addr of the radio.
   * Not populated by the phone, but added by the esp32 when broadcasting
   *
   * @deprecated
   */
  macaddr: Uint8Array;
  /**
   * TBEAM, HELTEC, etc...
   * Starting in 1.2.11 moved to hw_model enum in the NodeInfo object.
   * Apps will still need the string here for older builds
   * (so OTA update can find the right image), but if the enum is available it will be used instead.
   */
  hwModel: HardwareModel;
  /**
   * In some regions Ham radio operators have different bandwidth limitations than others.
   * If this user is a licensed operator, set this flag.
   * Also, "long_name" should be their licence number.
   */
  isLicensed: boolean;
  /** Indicates that the user's role in the mesh */
  role: Config_DeviceConfig_Role;
  /**
   * The public key of the user's device.
   * This is sent out to other nodes on the mesh to allow them to compute a shared secret key.
   */
  publicKey: Uint8Array;
  /** Whether or not the node can be messaged */
  isUnmessagable?: boolean | undefined;
}

/** A message used in a traceroute */
export interface RouteDiscovery {
  /** The list of nodenums this packet has visited so far to the destination. */
  route: number[];
  /** The list of SNRs (in dB, scaled by 4) in the route towards the destination. */
  snrTowards: number[];
  /** The list of nodenums the packet has visited on the way back from the destination. */
  routeBack: number[];
  /** The list of SNRs (in dB, scaled by 4) in the route back from the destination. */
  snrBack: number[];
}

/** A Routing control Data packet handled by the routing module */
export interface Routing {
  /** A route request going from the requester */
  routeRequest?:
    | RouteDiscovery
    | undefined;
  /** A route reply */
  routeReply?:
    | RouteDiscovery
    | undefined;
  /**
   * A failure in delivering a message (usually used for routing control messages, but might be provided
   * in addition to ack.fail_id to provide details on the type of failure).
   */
  errorReason?: Routing_Error | undefined;
}

/**
 * A failure in delivering a message (usually used for routing control messages, but might be provided in addition to ack.fail_id to provide
 * details on the type of failure).
 */
export enum Routing_Error {
  /** NONE - This message is not a failure */
  NONE = 0,
  /** NO_ROUTE - Our node doesn't have a route to the requested destination anymore. */
  NO_ROUTE = 1,
  /** GOT_NAK - We received a nak while trying to forward on your behalf */
  GOT_NAK = 2,
  /** TIMEOUT - TODO: REPLACE */
  TIMEOUT = 3,
  /** NO_INTERFACE - No suitable interface could be found for delivering this packet */
  NO_INTERFACE = 4,
  /** MAX_RETRANSMIT - We reached the max retransmission count (typically for naive flood routing) */
  MAX_RETRANSMIT = 5,
  /** NO_CHANNEL - No suitable channel was found for sending this packet (i.e. was requested channel index disabled?) */
  NO_CHANNEL = 6,
  /** TOO_LARGE - The packet was too big for sending (exceeds interface MTU after encoding) */
  TOO_LARGE = 7,
  /**
   * NO_RESPONSE - The request had want_response set, the request reached the destination node, but no service on that node wants to send a response
   * (possibly due to bad channel permissions)
   */
  NO_RESPONSE = 8,
  /** DUTY_CYCLE_LIMIT - Cannot send currently because duty cycle regulations will be violated. */
  DUTY_CYCLE_LIMIT = 9,
  /** BAD_REQUEST - The application layer service on the remote node received your request, but considered your request somehow invalid */
  BAD_REQUEST = 32,
  /**
   * NOT_AUTHORIZED - The application layer service on the remote node received your request, but considered your request not authorized
   * (i.e you did not send the request on the required bound channel)
   */
  NOT_AUTHORIZED = 33,
  /** PKI_FAILED - The client specified a PKI transport, but the node was unable to send the packet using PKI (and did not send the message at all) */
  PKI_FAILED = 34,
  /** PKI_UNKNOWN_PUBKEY - The receiving node does not have a Public Key to decode with */
  PKI_UNKNOWN_PUBKEY = 35,
  /** ADMIN_BAD_SESSION_KEY - Admin packet otherwise checks out, but uses a bogus or expired session key */
  ADMIN_BAD_SESSION_KEY = 36,
  /** ADMIN_PUBLIC_KEY_UNAUTHORIZED - Admin packet sent using PKC, but not from a public key on the admin key list */
  ADMIN_PUBLIC_KEY_UNAUTHORIZED = 37,
  /**
   * RATE_LIMIT_EXCEEDED - Airtime fairness rate limit exceeded for a packet
   * This typically enforced per portnum and is used to prevent a single node from monopolizing airtime
   */
  RATE_LIMIT_EXCEEDED = 38,
  /**
   * PKI_SEND_FAIL_PUBLIC_KEY - PKI encryption failed, due to no public key for the remote node
   * This is different from PKI_UNKNOWN_PUBKEY which indicates a failure upon receiving a packet
   */
  PKI_SEND_FAIL_PUBLIC_KEY = 39,
  UNRECOGNIZED = -1,
}

export function routing_ErrorFromJSON(object: any): Routing_Error {
  switch (object) {
    case 0:
    case "NONE":
      return Routing_Error.NONE;
    case 1:
    case "NO_ROUTE":
      return Routing_Error.NO_ROUTE;
    case 2:
    case "GOT_NAK":
      return Routing_Error.GOT_NAK;
    case 3:
    case "TIMEOUT":
      return Routing_Error.TIMEOUT;
    case 4:
    case "NO_INTERFACE":
      return Routing_Error.NO_INTERFACE;
    case 5:
    case "MAX_RETRANSMIT":
      return Routing_Error.MAX_RETRANSMIT;
    case 6:
    case "NO_CHANNEL":
      return Routing_Error.NO_CHANNEL;
    case 7:
    case "TOO_LARGE":
      return Routing_Error.TOO_LARGE;
    case 8:
    case "NO_RESPONSE":
      return Routing_Error.NO_RESPONSE;
    case 9:
    case "DUTY_CYCLE_LIMIT":
      return Routing_Error.DUTY_CYCLE_LIMIT;
    case 32:
    case "BAD_REQUEST":
      return Routing_Error.BAD_REQUEST;
    case 33:
    case "NOT_AUTHORIZED":
      return Routing_Error.NOT_AUTHORIZED;
    case 34:
    case "PKI_FAILED":
      return Routing_Error.PKI_FAILED;
    case 35:
    case "PKI_UNKNOWN_PUBKEY":
      return Routing_Error.PKI_UNKNOWN_PUBKEY;
    case 36:
    case "ADMIN_BAD_SESSION_KEY":
      return Routing_Error.ADMIN_BAD_SESSION_KEY;
    case 37:
    case "ADMIN_PUBLIC_KEY_UNAUTHORIZED":
      return Routing_Error.ADMIN_PUBLIC_KEY_UNAUTHORIZED;
    case 38:
    case "RATE_LIMIT_EXCEEDED":
      return Routing_Error.RATE_LIMIT_EXCEEDED;
    case 39:
    case "PKI_SEND_FAIL_PUBLIC_KEY":
      return Routing_Error.PKI_SEND_FAIL_PUBLIC_KEY;
    case -1:
    case "UNRECOGNIZED":
    default:
      return Routing_Error.UNRECOGNIZED;
  }
}

